// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title DecentralizedFileAuction
 * @notice Users upload file hashes and bid on storage slots.
 *         Winners are selected via verifiable randomness.
 */
contract DecentralizedFileAuction is Ownable, ReentrancyGuard {
    struct Upload {
        bytes32 fileHash;
        address uploader;
        uint256 timestamp;
        uint256 bidAmount;
        bool settled;
    }

    struct Epoch {
        uint256 startBlock;
        uint256 endBlock;
        bytes32 entropyAccumulator;
        uint256 uploadCount;
        bool finalized;
    }

    mapping(uint256 => Epoch) public epochs;
    mapping(uint256 => mapping(uint256 => Upload)) public uploads;
    mapping(address => uint256) public pendingWithdrawals;

    uint256 public currentEpoch;
    uint256 public constant EPOCH_LENGTH = 50;
    uint256 public constant MAX_WINNERS = 3;
    uint256 public constant MIN_BID = 0.01 ether;

    event UploadSubmitted(uint256 indexed epoch, uint256 indexed index, address uploader);
    event EpochFinalized(uint256 indexed epoch, uint256[] winners);
    event Withdrawal(address indexed user, uint256 amount);

    constructor() {
        _initEpoch();
    }

    function _initEpoch() internal {
        currentEpoch++;
        epochs[currentEpoch] = Epoch({
            startBlock: block.number,
            endBlock: block.number + EPOCH_LENGTH,
            entropyAccumulator: keccak256(abi.encodePacked(block.prevrandao, address(this))),
            uploadCount: 0,
            finalized: false
        });
    }

    /**
     * @notice Submit a file hash with a bid for the current epoch
     * @param _fileHash The keccak256 hash of the file content
     */
    function submitUpload(bytes32 _fileHash) external payable nonReentrant {
        require(msg.value >= MIN_BID, "Bid too low");
        require(_fileHash != bytes32(0), "Empty hash");

        Epoch storage epoch = epochs[currentEpoch];
        require(block.number <= epoch.endBlock, "Epoch ended");

        uint256 index = epoch.uploadCount;
        uploads[currentEpoch][index] = Upload({
            fileHash: _fileHash,
            uploader: msg.sender,
            timestamp: block.timestamp,
            bidAmount: msg.value,
            settled: false
        });

        // Mix user's contribution into entropy accumulator
        epoch.entropyAccumulator = keccak256(
            abi.encodePacked(
                epoch.entropyAccumulator,
                _fileHash,
                msg.sender,
                msg.value
            )
        );
        epoch.uploadCount++;

        emit UploadSubmitted(currentEpoch, index, msg.sender);
    }

    /**
     * @notice Finalize the epoch and select winners using accumulated entropy
     * @dev Uses a multi-source entropy derivation to resist manipulation
     */
    function finalizeEpoch() external nonReentrant {
        Epoch storage epoch = epochs[currentEpoch];
        require(block.number > epoch.endBlock, "Epoch not ended");
        require(!epoch.finalized, "Already finalized");
        require(epoch.uploadCount > 0, "No uploads");

        epoch.finalized = true;

        // Derive final seed from multiple sources
        bytes32 finalSeed = _deriveSeed(epoch);

        uint256 numWinners = epoch.uploadCount < MAX_WINNERS ? epoch.uploadCount : MAX_WINNERS;
        uint256[] memory winners = new uint256[](numWinners);

        // Select winners using derived randomness
        for (uint256 i = 0; i < numWinners; i++) {
            uint256 winnerIndex = _selectWinner(finalSeed, i, epoch.uploadCount, winners, numWinners);
            winners[i] = winnerIndex;
            uploads[currentEpoch][winnerIndex].settled = true;
        }

        // Distribute rewards to non-winners
        _distributeRefunds(epoch.uploadCount, winners, numWinners);

        emit EpochFinalized(currentEpoch, winners);
        _initEpoch();
    }

    /**
     * @dev Derives a seed combining the entropy accumulator with block-level data.
     *      The accumulator already contains all user inputs mixed via keccak256.
     */
    function _deriveSeed(Epoch storage epoch) internal view returns (bytes32) {
        // Combine accumulator with the blockhash of the epoch's end block
        // This adds a source the users couldn't have predicted at submission time
        bytes32 blockEntropy = blockhash(epoch.endBlock);

        // If blockhash is unavailable (>256 blocks ago), revert to prevent
        // predictable randomness from being used
        require(blockEntropy != bytes32(0), "Block entropy unavailable, epoch too old");

        return keccak256(
            abi.encodePacked(
                epoch.entropyAccumulator,
                blockEntropy,
                epoch.uploadCount
            ));
    }

    function _selectWinner(
        bytes32 seed,
        uint256 round,
        uint256 totalUploads,
        uint256[] memory previousWinners,
        uint256 numSelected
    ) internal pure returns (uint256) {
        uint256 candidate;
        uint256 nonce = 0;

        while (true) {
            candidate = uint256(keccak256(abi.encodePacked(seed, round, nonce))) % totalUploads;

            bool isDuplicate = false;
            for (uint256 j = 0; j < round; j++) {
                if (previousWinners[j] == candidate) {
                    isDuplicate = true;
                    break;
                }
            }

            if (!isDuplicate) return candidate;
            nonce++;
        }

        return candidate; // unreachable
    }

    function _distributeRefunds(
        uint256 totalUploads,
        uint256[] memory winners,
        uint256 numWinners
    ) internal {
        for (uint256 i = 0; i < totalUploads; i++) {
            bool isWinner = false;
            for (uint256 j = 0; j < numWinners; j++) {
                if (winners[j] == i) {
                    isWinner = true;
                    break;
                }
            }
            if (!isWinner) {
                Upload storage upload = uploads[currentEpoch][i];
                pendingWithdrawals[upload.uploader] += upload.bidAmount;
            }
        }
    }

    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        require(amount > 0, "Nothing to withdraw");
        pendingWithdrawals[msg.sender] = 0;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
        emit Withdrawal(msg.sender, amount);
    }

    receive() external payable {}
}
